package pe.com.dentalamericana.finance;import jakarta.persistence.*;import java.math.BigDecimal;import java.time.Instant;@Entity@Table(name="pagos")public class Payment{@Id@GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(name="cuenta_id",nullable=false)private Long accountId;@Column(name="paciente_id",nullable=false)private Long patientId;@Column(name="plan_id",nullable=false)private Long planId;@Column(name="sesion_caja_id",nullable=false)private Long cashSessionId;@Column(name="metodo_pago_id",nullable=false)private Long paymentMethodId;@Column(nullable=false)private BigDecimal monto;private String referencia;@Column(name="numero_constancia",nullable=false,unique=true)private String receiptNumber;@Enumerated(EnumType.STRING)@Column(nullable=false)private FinancialRecordStatus estado;@Column(name="registrado_por",nullable=false)private Long registeredBy;@Column(name="confirmado_por",nullable=false)private Long confirmedBy;@Column(name="registrado_en",nullable=false,updatable=false)private Instant registeredAt;@Version private Long version;protected Payment(){}public Payment(Long accountId,Long patientId,Long planId,Long sessionId,Long methodId,BigDecimal amount,String reference,String receipt,Long actor){this.accountId=accountId;this.patientId=patientId;this.planId=planId;this.cashSessionId=sessionId;this.paymentMethodId=methodId;this.monto=amount;this.referencia=reference;this.receiptNumber=receipt;this.estado=FinancialRecordStatus.REGISTRADO;this.registeredBy=actor;this.confirmedBy=actor;}@PrePersist void create(){registeredAt=Instant.now();}public Long getId(){return id;}public Long getAccountId(){return accountId;}public Long getPatientId(){return patientId;}public Long getPlanId(){return planId;}public Long getCashSessionId(){return cashSessionId;}public Long getPaymentMethodId(){return paymentMethodId;}public BigDecimal getAmount(){return monto;}public String getReference(){return referencia;}public String getReceiptNumber(){return receiptNumber;}public FinancialRecordStatus getStatus(){return estado;}public Instant getRegisteredAt(){return registeredAt;}public Long getVersion(){return version;}}
